.featured-list{display:grid;gap:10px;margin:0;padding:0;list-style:none}.featured-list li{display:flex;gap:12px;font-size:14px}.featured-number{width:20px;flex-shrink:0;color:var(--signal);font-family:var(--font-data)}.featured-list a{color:var(--ink)}.featured-list a:hover{color:var(--signal)}.featured-empty{color:var(--mute-2);font-size:13px;line-height:1.6}
.widget-content ul{margin:0;padding:0;list-style:none}.widget-content li{margin:0 0 7px}.widget-content a:hover{color:var(--signal)}.widget.Followers{display:none!important}
.faq{border-top:1px solid var(--line);background:var(--panel-2)}.faq-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;padding-block:48px;text-align:center}.faq-number{display:flex;align-items:center;justify-content:center;gap:8px;margin:0 0 4px;font-family:var(--font-display);font-size:14px}.faq-item h3{margin:0 0 4px;font-family:var(--font-display);font-size:16px}.faq-item p{margin:0;color:var(--mute);font-size:14px;line-height:1.6}@keyframes chatpulse{0%,100%{opacity:1}50%{opacity:.35}}.chat{border-top:1px solid var(--line);background:var(--panel-2);padding-block:56px}#chat-app{height:480px;border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;background:var(--bg)}.xogalaxy-chat{display:flex;flex-direction:column;height:100%}.xogalaxy-chat .chat-status{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;margin:0;padding:10px 16px;border-bottom:1px solid var(--line);color:var(--mute);font-family:var(--font-data);font-size:12px}.chat-status-text{display:inline-flex;align-items:center;gap:8px}.chat-session{display:flex;align-items:center;gap:8px;margin-left:auto;min-width:0}.chat-session-id{display:inline-flex;align-items:center;gap:6px;max-width:100%;padding:2px 8px 2px 2px;color:var(--ink);background:transparent;border:1px solid transparent;border-radius:999px;font-family:var(--font-data);font-size:12px;cursor:pointer}.chat-session-id:hover{color:var(--signal);border-color:var(--line)}.chat-avatar{width:24px;height:24px;border-radius:50%;object-fit:cover;background:var(--panel);flex-shrink:0}.chat-who{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.chat-logout{flex-shrink:0;width:32px;height:32px;padding:0;display:inline-flex;align-items:center;justify-content:center;color:var(--mute);background:transparent;border:1px solid var(--line);border-radius:50%;cursor:pointer}.chat-logout svg{width:16px;height:16px}.chat-logout:hover{color:var(--ceibal);border-color:var(--ceibal)}.chat-google{min-width:0}.chat-guest{color:var(--mute);font-family:var(--font-data);font-size:11px;white-space:nowrap}.chat-msg-user{padding:0;background:transparent;border:0;cursor:pointer;font:inherit;color:var(--orbit)}.chat-msg-user:hover{color:var(--signal);text-decoration:underline}.xogalaxy-chat.chat-online .chat-status{color:var(--signal)}.xogalaxy-chat.chat-offline .chat-status{color:var(--ceibal)}.xogalaxy-chat .chat-status::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--mute-2);flex-shrink:0}.xogalaxy-chat.chat-online .chat-status::before{background:var(--signal);box-shadow:0 0 8px var(--signal);animation:chatpulse 1.4s ease-in-out infinite}.xogalaxy-chat.chat-offline .chat-status::before{background:var(--ceibal)}.chat-msgs{flex:1;margin:0;padding:12px 16px;overflow-y:auto;list-style:none;display:flex;flex-direction:column;gap:8px}.chat-msg{font-size:14px;line-height:1.5;word-break:break-word}.chat-msg-meta{color:var(--orbit);font-family:var(--font-data);font-size:11px;margin-right:8px;font-weight:700}.chat-msg-body{color:var(--ink)}.chat-form{display:flex;gap:8px;padding:10px;border-top:1px solid var(--line);background:var(--panel)}.chat-form input{min-width:0;padding:9px 12px;color:var(--ink);background:var(--bg);border:1px solid var(--line);border-radius:6px;font-size:14px}.chat-form input:focus{outline:none;border-color:var(--orbit);box-shadow:0 0 0 1px var(--orbit)}.chat-form .chat-nick{width:110px;flex-shrink:0}.chat-form .chat-input{flex:1}.chat-send{flex-shrink:0;padding:9px 16px;color:var(--void);background:var(--signal);border:1px solid var(--signal);border-radius:6px;font-family:var(--font-display);font-size:12px;font-weight:700}.chat-send:hover{background:var(--signal-dim);border-color:var(--signal-dim)}.chat-note{display:flex;align-items:center;justify-content:center;gap:8px;margin:12px 0 0;color:var(--mute);font-family:var(--font-data);font-size:12px;text-align:center}
footer{border-top:1px solid var(--line)}.footer-inner{display:flex;flex-direction:column;align-items:center;gap:20px;padding-block:40px;text-align:center}.footer-logo{display:flex;align-items:center;gap:8px;font-family:var(--font-display);font-size:14px}.footer-dot{width:8px;height:8px;border-radius:50%;background:var(--signal)}.footer-nav{display:flex;flex-wrap:wrap;justify-content:center;gap:8px 24px;color:var(--mute);font-family:var(--font-data);font-size:12px}.footer-nav a{display:inline-flex;align-items:center;gap:6px}.footer-nav a:hover{color:var(--signal)}.copyright{margin:0;color:var(--mute-2);font-size:11px}.footer-credit{margin:0;color:var(--mute-2);font-size:11px}.footer-credit a{color:var(--signal)}.footer-credit a:hover{text-decoration:underline}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
@keyframes spin{to{transform:rotate(360deg)}}@keyframes spin-reverse{to{transform:rotate(-360deg)}}@keyframes blink{50%{opacity:0}}@keyframes rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:translateY(0)}}
@media (prefers-reduced-motion:no-preference){.orbit{animation:spin 22s linear infinite;transform-origin:50% 50%}.orbit.second{animation:spin-reverse 30s linear infinite}.blink{animation:blink 1.4s steps(1) infinite}.post{animation:rise .6s cubic-bezier(.16,1,.3,1) both}.post:nth-child(2){animation-delay:.05s}.post:nth-child(3){animation-delay:.1s}.post:nth-child(4){animation-delay:.15s}.post:nth-child(5){animation-delay:.2s}.post:nth-child(6){animation-delay:.25s}}
@media (max-width:900px){.main-layout{grid-template-columns:1fr;gap:40px}.sidebar{position:static;grid-template-columns:repeat(2,minmax(0,1fr));align-items:start}.sidebar-card:first-child{grid-column:1/-1}.newsletter-inner{align-items:stretch;flex-direction:column}.newsletter-form{max-width:none}.post,.post:has(.post-cover){grid-template-columns:1fr}.post-title{font-size:24px}.nav-toggle{display:flex;align-items:center;justify-content:center;gap:8px;margin:28px auto 0;min-height:44px;padding:10px 16px;color:var(--ink);background:var(--panel);border:1px solid var(--line);border-radius:999px;font-family:var(--font-display);font-size:13px;font-weight:700;cursor:pointer}.nav-toggle:hover{color:var(--signal);border-color:var(--signal)}.main-nav{position:fixed;z-index:80;top:0;right:0;bottom:0;width:min(320px,85vw);margin:0;padding:24px;align-items:stretch;flex-direction:column;justify-content:flex-start;gap:4px;background:var(--panel);border-left:1px solid var(--line);box-shadow:-20px 0 40px rgba(0,0,0,.35);transform:translateX(100%);transition:transform .3s cubic-bezier(.16,1,.3,1);overflow-y:auto}.main-nav .nav-link,.main-nav .dropdown-toggle{justify-content:flex-start}.main-nav .dropdown-menu{position:static;width:100%;margin-top:6px;box-shadow:none}.main-nav .search-box{width:100%;margin:8px 0 0}body.nav-open{overflow:hidden}body.nav-open .main-nav{transform:translateX(0)}.nav-backdrop{position:fixed;z-index:70;inset:0;background:rgba(0,0,0,.55);opacity:0;pointer-events:none;transition:opacity .3s}body.nav-open .nav-backdrop{opacity:1;pointer-events:auto}}
@media (max-width:640px){.container{width:min(calc(100% - 28px),var(--container))}.status-inner{justify-content:center;text-align:center}.status-nav{display:none}.hero-inner{padding-top:48px;padding-bottom:56px}.orbital-logo{width:96px;height:96px}.orbit.second{inset:10px}.orbit-center:after{width:30px;height:30px}.hero-kicker{font-size:10px;letter-spacing:.22em}.hero-description{font-size:14px;line-height:1.7}.hero-actions{width:100%;flex-direction:column}.hero-actions .btn{width:100%}.newsletter-text{align-items:flex-start;text-align:center}.newsletter-form{flex-direction:column}.newsletter-form button{width:100%}.tag-cloud-inner{gap:7px 12px}.main-layout{padding-top:40px;padding-bottom:40px}.section-heading{flex-wrap:wrap}.heading-meta{width:100%}#feed .section-heading{flex-wrap:nowrap}#feed .heading-meta{width:auto}.share-row{justify-content:center}.share-row-label{width:100%;justify-content:center}.post{padding:18px}.post-footer{align-items:flex-start;flex-direction:column;gap:8px}.sidebar{grid-template-columns:1fr}.sidebar-card:first-child{grid-column:auto}.faq-grid{grid-template-columns:1fr;gap:32px;padding-block:40px}.chat{padding-block:40px}.chat-box{height:400px}.stats{grid-template-columns:repeat(2,1fr)}.footer-nav{gap:10px 18px}}
@media (max-width:380px){.container{width:min(calc(100% - 20px),var(--container))}.hero h1{font-size:2rem}.post-meta{align-items:flex-start;flex-direction:column}.stats{gap:6px}.xo-grid{grid-template-columns:1fr}}
